import json
import sys
import os
import re
from typing import Dict, List, Tuple, Optional, Union

def parse_expression(expr: str) -> Tuple[str, float]:
    def tokenize(s: str) -> List[str]:
        tokens = []
        i = 0
        while i < len(s):
            if s[i] in '()+-*/%':
                tokens.append(s[i])
                i += 1
            elif s[i].isdigit() or s[i] == '.':
                j = i
                while j < len(s) and (s[j].isdigit() or s[j] == '.'):
                    j += 1
                tokens.append(s[i:j])
                i = j
            elif s[i].isalpha() or s[i] == '_':
                j = i
                while j < len(s) and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                tokens.append(s[i:j])
                i = j
            else:
                i += 1
        return tokens

    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    def evaluate(tokens: List[str]) -> float:
        stack = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token == '(':
                j = i + 1
                balance = 1
                while j < len(tokens) and balance > 0:
                    if tokens[j] == '(':
                        balance += 1
                    elif tokens[j] == ')':
                        balance -= 1
                    j += 1
                if j >= len(tokens):
                    raise ValueError("Unmatched parenthesis")
                sub_expr = tokens[i+1:j-1]
                stack.append(evaluate(sub_expr))
                i = j
            elif token == ')':
                raise ValueError("Unmatched parenthesis")
            elif token in '+-*/%//**':
                if len(stack) < 2:
                    raise ValueError("Invalid operator usage")
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    if b == 0:
                        raise ValueError("Division by zero")
                    stack.append(a / b)
                elif token == '//':
                    if b == 0:
                        raise ValueError("Division by zero")
                    stack.append(a // b)
                elif token == '%':
                    if b == 0:
                        raise ValueError("Division by zero")
                    stack.append(a % b)
                elif token == '**':
                    stack.append(a ** b)
            else:
                try:
                    num = float(token)
                    stack.append(num)
                except ValueError:
                    raise ValueError(f"Invalid number: {token}")
                i += 1
        if len(stack) != 1:
            raise ValueError("Invalid expression")
        return stack[0]

    try:
        return tokens[0], evaluate(tokens[1:])
    except ValueError as e:
        raise ValueError(f"Expression error: {e}")

def parse_rules_file(file_path: str) -> List[Tuple[str, str]]:
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    rules = []
    for i, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        parts = stripped.split('=', 1)
        if len(parts) != 2:
            raise ValueError(f"line {i}: malformed rule")
        name = parts[0].strip()
        expr = parts[1].strip()
        if not re.fullmatch(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
            raise ValueError(f"line {i}: invalid name '{name}'")
        rules.append((name, expr))
    return rules

def load_vars_file(file_path: str) -> Dict[str, float]:
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    return {k: float(v) for k, v in data.items()}

def evaluate_rules(rules: List[Tuple[str, str]], vars_dict: Dict[str, float]) -> List[Dict[str, float]]:
    results = []
    for name, expr in rules:
        try:
            parsed_name, value = parse_expression(expr)
            if parsed_name != name:
                raise ValueError(f"Name mismatch: expected '{name}', got '{parsed_name}'")
            if name not in vars_dict:
                raise ValueError(f"Variable '{name}' not found in variables")
            results.append({name: value})
        except ValueError as e:
            print(f"{name}: {str(e)}", file=sys.stderr)
            sys.exit(1)
    return results

def cache_rules(file_path: str, rules: List[Tuple[str, str]]) -> None:
    cache_path = f"{file_path}.cache"
    with open(cache_path, 'w', encoding='utf-8') as f:
        f.write(f"# Rules file: {file_path}\n")
        f.write("\n".join(rules) + "\n")
    with open(file_path, 'r', encoding='utf-8') as f:
        cache_content = f.read()
    with open(cache_path, 'a', encoding='utf-8') as f:
        f.write(f"# Cache content: {cache_content}\n")

def main():
    if len(sys.argv) != 3:
        print("Usage: python runrules.py RULES_FILE VARS_FILE", file=sys.stderr)
        sys.exit(2)

    rules_file = sys.argv[1]
    vars_file = sys.argv[2]

    cache_path = f"{rules_file}.cache"
    if os.path.exists(cache_path):
        with open(cache_path, 'r', encoding='utf-8') as f:
            cache_content = f.read()
        if cache_content.startswith("# Rules file: "):
            cached_rules_file = cache_content.split("# Rules file: ")[1].split("\n")[0]
            if cached_rules_file != rules_file:
                os.remove(cache_path)
                print(f"Cache file for {rules_file} is outdated, regenerating cache.", file=sys.stderr)
        else:
            os.remove(cache_path)

    try:
        with open(rules_file, 'r', encoding='utf-8') as f:
            rules = parse_rules_file(rules_file)
    except ValueError as e:
        print(f"line {e.args[0]}: {e.args[1]}", file=sys.stderr)
        sys.exit(2)

    if os.path.exists(cache_path):
        with open(cache_path, 'r', encoding='utf-8') as f:
            cache_content = f.read()
        if cache_content.startswith("# Rules file: "):
            cached_rules = []
            for line in cache_content.split("\n"):
                if line.strip() and not line.startswith("#"):
                    cached_rules.append(line.strip())
            if len(cached_rules) == len(rules):
                rules = cached_rules
            else:
                os.remove(cache_path)

    try:
        vars_dict = load_vars_file(vars_file)
    except json.JSONDecodeError:
        print("Invalid JSON in VARS_FILE", file=sys.stderr)
        sys.exit(1)

    results = evaluate_rules(rules, vars_dict)
    for result in results:
        print(json.dumps(result))

    cache_rules(rules_file, rules)
    sys.exit(0)

if __name__ == "__main__":
    main()

import json
import sys
from functools import lru_cache
from typing import Dict, List, Any, Optional, Union

class RuleEvaluator:
    def __init__(self):
        self.cache = {}
        self.failed_rules = []

    def load_rules(self, rules_file: str) -> List[Dict[str, Any]]:
        with open(rules_file, 'r') as f:
            return json.load(f)

    def load_variables(self, variables_file: str) -> Dict[str, Any]:
        with open(variables_file, 'r') as f:
            return json.load(f)

    def evaluate_rule(self, rule: Dict[str, Any], variables: Dict[str, Any], cache_key: str) -> Optional[bool]:
        if cache_key in self.cache:
            return self.cache[cache_key]

        try:
            expression = rule['expression']
            for var_name, var_value in variables.items():
                expression = expression.replace(f'{{{var_name}}}', str(var_value))

            result = eval(expression, {'__builtins__': None}, {**self.cache, **variables})
            self.cache[cache_key] = result
            return result
        except Exception as e:
            self.failed_rules.append(rule)
            return None

    def evaluate_rules(self, rules: List[Dict[str, Any]], variables: Dict[str, Any]) -> List[Dict[str, Any]]:
        results = []
        for rule in rules:
            cache_key = f"{rule.get('id', '')}_{rule.get('expression', '')}"
            result = self.evaluate_rule(rule, variables, cache_key)
            results.append({
                'id': rule.get('id'),
                'expression': rule.get('expression'),
                'result': result,
                'failed': result is None
            })
        return results

def main():
    if len(sys.argv) != 4:
        print("Usage: python rule_evaluator.py <rules_file.json> <variables_file.json>")
        sys.exit(1)

    evaluator = RuleEvaluator()
    rules = evaluator.load_rules(sys.argv[1])
    variables = evaluator.load_variables(sys.argv[2])

    results = evaluator.evaluate_rules(rules, variables)

    for result in results:
        if result['failed']:
            print(f"Rule {result.get('id', 'unnamed')} failed: {result['expression']}")
        else:
            print(f"Rule {result.get('id', 'unnamed')} passed: {result['expression']} -> {result['result']}")

if __name__ == "__main__":
    main()

import json
import os
from functools import lru_cache
from typing import Dict, List, Any, Optional

def load_rules_file(file_path: str) -> List[Dict[str, Any]]:
    try:
        with open(file_path, 'r') as file:
            return json.load(file)
    except Exception as e:
        print(f"Error loading rules file: {e}")
        return []

def load_variables_file(file_path: str) -> Dict[str, Any]:
    try:
        with open(file_path, 'r') as file:
            return json.load(file)
    except Exception as e:
        print(f"Error loading variables file: {e}")
        return {}

def evaluate_rule(rule: Dict[str, Any], variables: Dict[str, Any], cache: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    try:
        rule_id = rule.get('id')
        if rule_id in cache:
            return cache[rule_id]

        # Execute the rule logic
        result = {}
        if 'condition' in rule:
            if not evaluate_condition(rule['condition'], variables):
                return None

        if 'action' in rule:
            if 'cache_key' in rule['action']:
                cache_key = f"{rule_id}_{rule['action']['cache_key']}"
                if cache_key in cache:
                    return cache[cache_key]

            # Apply actions
            for action in rule['action']:
                if action['type'] == 'set':
                    for key, value in action['value'].items():
                        variables[key] = value
                elif action['type'] == 'log':
                    print(f"[LOG] {action['message']}")

        # Cache the result if applicable
        if 'cache_key' in rule['action']:
            cache_key = f"{rule_id}_{rule['action']['cache_key']}"
            cache[cache_key] = result

        return result
    except Exception as e:
        print(f"Error evaluating rule {rule.get('id')}: {e}")
        return None

def evaluate_condition(condition: Dict[str, Any], variables: Dict[str, Any]) -> bool:
    try:
        if 'type' not in condition:
            return True

        if condition['type'] == 'equals':
            return variables.get(condition['value']) == condition['value']
        elif condition['type'] == 'greater_than':
            return variables.get(condition['value']) > condition['value']
        elif condition['type'] == 'less_than':
            return variables.get(condition['value']) < condition['value']
        elif condition['type'] == 'contains':
            return condition['value'] in variables.get(condition['value'], '')
        elif condition['type'] == 'in':
            return variables.get(condition['value']) in condition['values']
        else:
            return False
    except Exception as e:
        print(f"Error evaluating condition: {e}")
        return False

def process_rules(rules: List[Dict[str, Any]], variables: Dict[str, Any]) -> Dict[str, Any]:
    cache = {}
    results = {}

    for rule in rules:
        try:
            result = evaluate_rule(rule, variables, cache)
            if result:
                results[rule.get('id')] = result
        except Exception as e:
            print(f"Error processing rule {rule.get('id')}: {e}")

    return results

def main():
    rules_file = 'rules.json'
    variables_file = 'variables.json'

    if not os.path.exists(rules_file) or not os.path.exists(variables_file):
        print("Error: Rules or variables file not found.")
        return

    rules = load_rules_file(rules_file)
    variables = load_variables_file(variables_file)

    if not rules:
        print("No rules loaded.")
        return

    results = process_rules(rules, variables)
    print("Evaluation results:", results)

if __name__ == "__main__":
    main()

import json
import sys
from typing import Dict, List, Any, Optional, Set
from functools import lru_cache

class RuleEvaluator:
    def __init__(self, cache_enabled: bool = False):
        self.cache_enabled = cache_enabled
        self.cache: Dict[str, Any] = {}

    def _get_cache_key(self, rule_id: str, variables: Dict[str, Any]) -> str:
        return f"{rule_id}_{json.dumps(variables, sort_keys=True)}"

    def _apply_cache(self, rule_id: str, variables: Dict[str, Any], result: Any) -> Any:
        if self.cache_enabled:
            cache_key = self._get_cache_key(rule_id, variables)
            if cache_key in self.cache:
                return self.cache[cache_key]
            self.cache[cache_key] = result
        return result

    def _evaluate_rule(self, rule: Dict[str, Any], variables: Dict[str, Any]) -> Any:
        try:
            rule_id = rule.get("id")
            if not rule_id:
                raise ValueError("Rule must have an 'id' field")

            if "condition" in rule:
                condition = rule["condition"]
                if isinstance(condition, str):
                    condition = eval(condition, {"__builtins__": None}, variables)
                else:
                    condition = eval(json.dumps(condition), {"__builtins__": None}, variables)

                if not condition:
                    return None

            if "action" in rule:
                action = rule["action"]
                if isinstance(action, str):
                    action = eval(action, {"__builtins__": None}, variables)
                else:
                    action = eval(json.dumps(action), {"__builtins__": None}, variables)

                return action(variables)
            return None
        except Exception as e:
            print(f"Error evaluating rule {rule_id}: {str(e)}", file=sys.stderr)
            return None

    def evaluate_rules(self, rules_file: str, variables_file: str) -> List[Any]:
        try:
            with open(rules_file, "r") as f:
                rules = json.load(f)
            with open(variables_file, "r") as f:
                variables = json.load(f)
        except json.JSONDecodeError as e:
            print(f"Invalid JSON in rules or variables file: {str(e)}", file=sys.stderr)
            return []
        except IOError as e:
            print(f"Error reading files: {str(e)}", file=sys.stderr)
            return []

        results = []
        for rule in rules:
            try:
                rule_id = rule.get("id")
                if rule_id not in [r.get("id") for r in rules if r.get("id")]:
                    print(f"Duplicate rule ID detected: {rule_id}", file=sys.stderr)
                    continue

                evaluated_result = self._evaluate_rule(rule, variables)
                results.append(self._apply_cache(rule_id, variables, evaluated_result))
            except Exception as e:
                print(f"Error processing rule {rule_id}: {str(e)}", file=sys.stderr)
                continue

        return results

def main():
    if len(sys.argv) != 4:
        print("Usage: python rule_evaluator.py <rules_file> <variables_file> <cache_enabled>", file=sys.stderr)
        sys.exit(1)

    rules_file = sys.argv[1]
    variables_file = sys.argv[2]
    cache_enabled = sys.argv[3].lower() == "true"

    evaluator = RuleEvaluator(cache_enabled=cache_enabled)
    results = evaluator.evaluate_rules(rules_file, variables_file)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
